import json
from pathlib import Path
from lesson_authoring import entry as E
W=[
E('obsolete','英 /ˈɒbsəliːt/；美 /ˌɑːbsəˈliːt/，也读 /ˈɑːbsəliːt/','过时的；已被淘汰的；不再通用的','东西可能还能运转，但大家已经换了做法，它退出了日常使用。','来自拉丁 obsoletus，是 obsolescere 逐渐不用的过去分词。更早可能含 ob- 离开 + solere 习惯使用，但这一远层拆解不是定论。',[['拉丁 obsolescere → obsoletus','逐渐不用 → 已过时、磨旧'],['英语 obsolete','已淘汰、不再使用']],'obsolete equipment 是已被更合适设备取代的旧设备，不一定每台都坏了。词典把某个词义标 obsolete，通常表示它已经退出一般使用，不是说这个拼写从未存在过。','become obsolete；render something obsolete；obsolete technology。','old 只是年代久，obsolete 强调不再适用或被淘汰。一个古老的方法仍很实用，就不必叫 obsolete。',('The new system made the old equipment obsolete.','新系统使旧设备被淘汰了。'),('This dictionary marks that meaning as obsolete.','这部词典把那个词义标为已废用。'),sources=['https://www.etymonline.com/word/obsolete','https://en.wiktionary.org/wiki/obsolete']),
E('obsolescent','英 /ˌɒbsəˈlesənt/；美 /ˌɑːbsəˈlesənt/','逐渐过时的；正在被淘汰的','还看得见、也有人在用，但正在一步步退出主流。','来自拉丁 obsolescens，动词 obsolescere 的现在分词。-escent 这一段保留逐渐进入某状态的意思。',[['拉丁 obsolescere → obsolescens','逐渐不用 → 正在变旧、退出使用'],['英语 obsolescent','逐渐被淘汰的']],'obsolete 常看淘汰后的状态，obsolescent 看正在走向淘汰的阶段。例如仍在维护、却越来越少有人采用的技术，可以称 obsolescent。它比普通 outdated 更正式。','obsolescent equipment；an obsolescent technology；becoming obsolescent。','obsolescent 不是 adolescent 青少年的。两者词尾相似，是因为都有变化、生长的构词背景，具体词根和含义不同。',('The factory still relies on obsolescent machinery.','这家工厂仍依赖正在被淘汰的机器。'),('The once popular format is now obsolescent.','这种曾经流行的格式如今正逐渐过时。'),sources=['https://www.etymonline.com/word/obsolescent']),
E('obsolescence','英 /ˌɒbsəˈlesəns/；美 /ˌɑːbsəˈlesəns/','过时；淘汰；逐渐退出使用','一项技术从人人都用，到慢慢没人再需要，这整个变化就是它走向淘汰的过程。','与 obsolescent 配套的名词形式，-ence 表状态或过程；上溯拉丁 obsolescere 逐渐不用及其分词词干。',[['拉丁 obsolescere／obsolescens','逐渐不用、正在过时'],['英语 obsolescent → obsolescence','逐渐过时的 → 过时的过程或状态']],'technological obsolescence 是技术更新造成旧东西过时。planned obsolescence 是有计划地让产品较早失去使用价值或吸引力，从而促使更换；普通磨损并不自动等于这种做法。','rapid obsolescence；technological obsolescence；planned obsolescence。','obsolescence 可以发生在设备还能工作的情况下；wear and tear 是使用造成的磨损。一个说被时代或需要淘汰，一个说物理损耗。',('Rapid obsolescence makes this equipment expensive to maintain.','设备很快过时，使维护它的成本很高。'),('The book discusses planned obsolescence in consumer products.','这本书讨论了消费产品中的计划性淘汰。'),sources=['https://www.etymonline.com/word/obsolescence','https://en.wiktionary.org/wiki/obsolescence']),
E('insolent','/ˈɪnsələnt/','傲慢无礼的；放肆的','对方不是没听清，而是摆出“我根本不把你当回事”的态度。','拉丁 in- 不 + solens 习惯的，形成 insolens 不寻常的、过分的、傲慢的；英语经拉丁或法语传统借入，保留傲慢无礼义。',[['拉丁 solere → solens','习惯于 → 惯常的'],['in- + solens → insolens','不寻常；过分、傲慢'],['英语 insolent','傲慢无礼的']],'an insolent reply 是带着轻慢、不尊重意味的回答。远源的“不寻常”已不能直接当现代解释：有创新、不守旧的人并不因此 insolent，关键是无礼和轻慢。','an insolent reply；an insolent tone；insolent behavior。','confident 是自信，insolent 是傲慢无礼。坚定表达不同意见可以很礼貌，不该把这两种态度混为一谈。',('She objected to his insolent tone.','她不满他那种傲慢无礼的语气。'),('His insolent reply ended the conversation.','他那句无礼的回答让谈话结束了。'),sources=['https://www.etymonline.com/word/insolent','https://en.wiktionary.org/wiki/insolent']),
E('insolence','/ˈɪnsələns/','傲慢无礼；放肆','把那种轻慢别人的语气和举动，作为一种行为来谈。','来自拉丁 insolentia，可能经法语 insolence；拉丁名词本来就有过分、傲慢等义。不是必须先有现代英语 insolent 才造出这个词。',[['拉丁 insolens → insolentia','过分、傲慢 → 这种状态和举止'],['法语／拉丁语 → 英语 insolence','傲慢无礼']],'His insolence surprised me 是他的无礼态度让我意外。常作为不可数名词谈一种行为或性质；不只是音量大，也不必包含脏话，轻蔑的冷笑也可以表现 insolence。','sheer insolence；an act of insolence；tolerate insolence。','insolence 是无礼，insolent 是无礼的。不能把 insolence 当 insult 的同义可数词，数一次次侮辱时通常用 insults。',('His insolence shocked the other guests.','他的傲慢无礼让其他客人很吃惊。'),('She mistook his nervousness for insolence.','她把他的紧张误当成了无礼。'),sources=['https://www.etymonline.com/word/insolence','https://en.wiktionary.org/wiki/insolence']),
E('insolently','/ˈɪnsələntli/','傲慢无礼地；放肆地','同样一句回答，配上轻蔑语气，就成了无礼地顶回去。','英语 insolent + -ly，把形容词变成描述动作方式的副词。',[['拉丁 insolens → 英语 insolent','傲慢无礼的'],['insolent + -ly → insolently','以傲慢无礼的方式']],'answered insolently 指回答的方式轻慢、放肆。副词强调怎么做，不改变 answer 本身“回答”的含义；句子可以不用脏字，仍表现出不尊重。','reply insolently；smile insolently；speak insolently。','insolently 不是 merely loudly 大声地，也不是 confidently 自信地。判断是否无礼，需要看语气和场景。',('He smiled insolently and refused to answer.','他轻蔑地笑了笑，拒绝回答。'),('She accused him of speaking insolently to the staff.','她指责他对工作人员说话傲慢无礼。'),sources=['https://en.wiktionary.org/wiki/insolently','https://www.etymonline.com/word/insolent'])
]
ROOT=dict(id='C1362',meaning='习惯于；惯常使用',core='SOLE = BE ACCUSTOMED',image='一条线是人们习惯怎样做，另一条线是旧东西渐渐退出使用。现代含义要分别看，不能只靠字面算式。',intro='拉丁 solere 是习惯于。insolent 的历史从不寻常、过分走到傲慢无礼；obsolete 来自逐渐不用的拉丁动词，它与 solere 的更早联系通常视为可能的分析。后者保留这点不确定，不编成已证实的直线。',forms='insolent／insolence 保留 solent- 这一分词词干。obsolete、obsolescent、obsolescence 分别便于记为已过时、正在过时、过时的过程或状态。本根与 sole 唯一的、鞋底等现代同形词不能混拆。',branches=[['退出使用','obsolete、obsolescent、obsolescence'],['轻慢与无礼','insolent、insolence、insolently']],contrasts='old 不必 obsolete，confident 不等于 insolent。词根解释词义的来路，实际用词仍由现代习惯决定。',practice='The equipment was becoming obsolete, but his insolent dismissal of the staff’s concerns helped no one.\n\n设备正在过时，可他傲慢地无视员工的担忧，对谁都没有帮助。',words=[x['word'] for x in W],exclude={})
